# owner: platform
"""Find unstaffed stretches of opening hours."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span
from hourglass.merging import merge_spans


def _check_inside(busy: List[Span], hours: Span) -> None:
    for span in busy:
        if span.start < hours.start or span.end > hours.end:
            text = format_span(span)
            raise ValueError(f"span outside hours: {text}")


def _gap_spans(busy: List[Span], hours: Span) -> List[Span]:
    ends = [hours.start] + [span.end for span in busy]
    starts = [span.start for span in busy] + [hours.end]
    return [
        Span(low, high)
        for low, high in zip(ends, starts)
        if low < high
    ]


def _label(gap: Span) -> str:
    return f"gap {format_span(gap)} ({gap.minutes} min)"


# ---
def find_gaps(
    spans: Iterable[Span], hours: Span
) -> List[str]:
    """One label per uncovered stretch of hours."""
    busy = merge_spans(spans)
    _check_inside(busy, hours)
    return [_label(gap) for gap in _gap_spans(busy, hours)]
